import Foundation
import SwiftRenderKit

// MARK: - The API guide, by topic
//
// docs/ai-quickstart.md is embedded verbatim (QuickstartText.swift, regenerated by
// `python3 scripts/embed-quickstart.py`; MCPCreateTests fails when it is stale) and served
// in topic-sized pieces by the `docs` tool and as `swift-render://docs/<topic>` resources, so
// an agent anywhere — no checkout, no web — writes a correct scene on the first try.

enum Guide {
    struct Topic {
        let id: String
        let title: String
        let summary: String
        /// Quickstart `## ` headings (prefixes) whose sections make up the topic.
        let headings: [String]
    }

    static let topics: [Topic] = [
        Topic(id: "scenes", title: "Writing a scene",
              summary: "The scene protocol, a template, timing windows, staggers, sizing, pitfalls and gotchas — read first",
              headings: ["Mental model", "Minimal scene template", "Multi-phase timing", "Letter-by-letter",
                         "Adapting to render size", "Common pitfalls", "Gotchas"]),
        Topic(id: "timeline", title: "Timeline",
              summary: "Timeline/Clip sequencing in local time, transitions, stagger",
              headings: ["Timeline"]),
        Topic(id: "easing", title: "Easing and springs",
              summary: "Ease.clip/easeOut/easeIn, analytic springs, back/elastic/bounce, cubic-bezier",
              headings: ["Easing reference", "Springs"]),
        Topic(id: "sound", title: "Score and sound",
              summary: "soundtrack(duration:) → Score: drums, harmony, transition marks (no whoosh/riser), samples, "
                + "voiceover, captions, audio-reactive scenes",
              headings: ["Soundtracks", "Samples, voiceover", "Voiceover levels", "Audio-reactive"]),
        Topic(id: "knobs", title: "Knobs, labels and props",
              summary: "Knob.double/color/text/bool, clip .named labels, PropsScene data-driven scenes",
              headings: ["Knobs and clip labels", "Props"]),
        Topic(id: "launch", title: "Launch films and LaunchKit",
              summary: "launch / init, the AppleLaunch props, LaunchKit components and their sound timings",
              headings: ["Launch films"]),
        Topic(id: "looks", title: "Shaders, looks and media",
              summary: "Metal shaders, dither/pixel/Stylize looks, video and image clips, vision tracking",
              headings: ["Using shaders", "Writing a new shader", "Look-dev", "Video and image clips", "Vision"]),
        Topic(id: "cli", title: "CLI",
              summary: "Every swift-render command, the make-a-video loop, fast iteration, long renders",
              headings: ["CLI reference", "The loop an agent", "Fast iteration", "Rendering long pieces"]),
        Topic(id: "review", title: "Review comments",
              summary: "Timecoded, region-boxed notes from people, and how to address them",
              headings: ["Review comments"]),
    ]

    /// Every topic id `docs` and `resources/read` accept: the index, the tool recipe, the
    /// topics above, `contributing` (this repo's own rules), `all` (the whole quickstart) and
    /// `more` when a section has no topic yet.
    static var topicIDs: [String] {
        ["index", "tools"] + topics.map(\.id) + ["contributing", "all"] + (unassigned.isEmpty ? [] : ["more"])
    }

    /// Bullets that only hold inside the swift-render repo (where its demo scenes live, its CI
    /// scripts): served under `contributing`, kept out of the topics an agent elsewhere reads.
    static let repoOnlyMarkers = ["`Sources/SwiftRenderScenes`", "scripts/typecheck-budget.sh"]

    static func isRepoOnly(_ line: Substring) -> Bool {
        line.hasPrefix("- ") && repoOnlyMarkers.contains { line.contains($0) }
    }

    /// `## Heading` → section text (heading line included), in file order.
    static let sections: [(heading: String, text: String)] = {
        var out: [(String, String)] = []
        var heading: String? = nil
        var lines: [Substring] = []
        func flush() {
            if let heading { out.append((heading, lines.joined(separator: "\n").trimmingCharacters(in: .whitespacesAndNewlines))) }
        }
        var inFence = false
        for line in QuickstartText.markdown.split(separator: "\n", omittingEmptySubsequences: false) {
            if line.hasPrefix("```") { inFence.toggle() }
            if !inFence, line.hasPrefix("## ") {
                flush()
                heading = String(line.dropFirst(3)); lines = [line]
            } else if heading != nil {
                lines.append(line)
            }
        }
        flush()
        return out
    }()

    private static func belongs(_ heading: String, to topic: Topic) -> Bool {
        topic.headings.contains { heading.hasPrefix($0) }
    }

    /// Sections no topic claims (none, while the map above is complete).
    static var unassigned: [(heading: String, text: String)] {
        sections.filter { s in !topics.contains { belongs(s.heading, to: $0) } }
    }

    /// The markdown for a topic id, or nil for an unknown one.
    static func text(_ id: String) -> String? {
        switch id {
        case "index": return index
        case "tools": return toolRecipe
        case "all": return QuickstartText.markdown
        case "more":
            let rest = unassigned
            return rest.isEmpty ? nil : rest.map(\.text).joined(separator: "\n\n")
        case "contributing":
            let lines = sections.flatMap { $0.text.split(separator: "\n").filter(isRepoOnly) }
            return "# \(title(id))\n\nOnly for work inside the swift-render repo itself (its demo scenes, its CI):\n\n"
                + lines.joined(separator: "\n")
        default:
            guard let topic = topics.first(where: { $0.id == id }) else { return nil }
            let body = sections.filter { belongs($0.heading, to: topic) }.map(\.text).joined(separator: "\n\n")
                .split(separator: "\n", omittingEmptySubsequences: false).filter { !isRepoOnly($0) }
                .joined(separator: "\n")
            return "# \(topic.title)\n\n\(body)"
        }
    }

    static func title(_ id: String) -> String {
        switch id {
        case "index": return "swift-render docs index"
        case "tools": return "Making videos with the swift-render MCP tools"
        case "all": return "AI Quickstart (everything)"
        case "contributing": return "Contributing to swift-render"
        case "more": return "More"
        default: return topics.first { $0.id == id }?.title ?? id
        }
    }

    static func summary(_ id: String) -> String {
        switch id {
        case "index": return "Start here: how to make a video, and what each topic covers"
        case "tools": return "Which MCP tool to call when, with examples"
        case "all": return "The whole docs/ai-quickstart.md in one piece (~25 KB)"
        case "contributing": return "Rules that only apply inside the swift-render repo (its demo scenes, its CI)"
        case "more": return "Quickstart sections not yet filed under a topic"
        default: return topics.first { $0.id == id }?.summary ?? ""
        }
    }

    /// The six-line recipe (initialize's instructions, the index, the tools topic).
    static let recipe = """
    How to make a video with swift-render (SwiftUI scenes rendered to MP4):
    1. docs {topic:"scenes"} once: the scene API in two pages (docs {} lists every topic).
    2. A Swift codebase to show off? launch_film {preview:true} scans it and renders an Apple-style launch film; look at the contact sheet it returns, fix copy with launch_film {props:{"tagline":"…"}}, then render without preview (aspect "9:16" for vertical).
    3. Your own film: new_scene {name} (outside a swift-render package call init_project first), then write body(at:duration:) as a pure function of t — edit the file, or without file tools send the whole source to write_scene.
    4. Look after every edit: contact_sheet {scene} or render_frames {scene, times}; data-driven scenes take get_props / set_props.
    5. check_scene before finishing (blank frames, loudness, no whoosh/riser), then render_video {scene} returns the MP4 path. Work that runs past ~45 s answers "job jN": poll render_status {job:"jN"} until done.
    6. Review notes from people: list_comments → get_comment → claim_comment → edit → render_frames {comment} → resolve_comment.
    """

    static var index: String {
        var lines = ["# swift-render docs", "", recipe, "", "## Topics (docs {topic} or resource swift-render://docs/<topic>)", ""]
        for id in topicIDs where id != "index" {
            lines.append("- `\(id)` — \(summary(id))")
        }
        lines += ["", HouseRules.text]
        return lines.joined(separator: "\n")
    }

    static let toolRecipe = """
    # Making videos with the swift-render MCP tools

    \(recipe)

    ## Which tool when

    - `launch_film {path?, aspect?, preview?, voiceover?, props?, rescan?}` — scan a Swift codebase (default: the
      workspace) and render the AppleLaunch film. Returns the MP4 path, what was detected (name, tagline,
      features, version, platforms, with the file each came from), the props file and a contact sheet. The props
      file is the film: `props` merges keys into it before rendering, `rescan:true` starts over.
    - `new_scene {name, kind?}` — scaffold `<Name>.swift` in the project's scenes folder (auto-registered) and
      return its source. `kind:"audio"` makes an AudioReactiveScene. Needs a swift-render project: `init_project`
      makes one. Names SwiftUI or swift-render already use (Text, Score, Timeline…) are refused.
    - `write_scene {name, source}` — for clients without file tools (Claude Desktop): create or replace the scene
      file with the whole source, build, and get the compiler diagnostics. `scene_info {scene, source:true}` reads one.
    - `init_project {path?}` — give a codebase its own `Launch/` package (your editable launch film as Swift + a
      `launch` CLI). The server switches to it and starts the first build as a job: new_scene, render_* and the
      review tools work there.
    - `render_status {job?, wait?, cancel?}` — render_video, launch_film, build and write_scene keep working in the
      background when they take more than ~45 s (some clients stop a tool call at ~60 s) and answer with a job id
      and the planned output. Poll this until it says done; it then returns the tool's result. `wait:true` on those
      tools blocks instead (clients without a time limit).
    - `get_props {scene}` / `set_props {scene, props, file?}` — read / save the JSON a data-driven scene renders
      (AppleLaunch, any PropsScene). Saved props are used by render_frames, contact_sheet, check_scene and
      render_video unless you pass `props` / `props_file`.
    - `list_scenes`, `scene_info {scene}` — what exists, and a scene's clips, knobs and score with file:line.
    - `contact_sheet`, `render_frames`, `check_scene` — LOOK. Images come back inline.
    - `render_video {scene, preview?, aspect?, props?}` — the MP4.
    - `set_knobs {scene, values}` — tune Knob.* constants without a rebuild.
    - Review loop: `list_comments`, `get_comment`, `claim_comment`, `reply_comment`, `resolve_comment`, `build`.

    ## Writing a scene in one breath

    ```swift
    import SwiftUI
    import SwiftRender

    public struct Hello: RenderScene {
        public static let defaultDuration: Double = 6
        static let bar = 60.0 / 110 * 4                      // 110 BPM: cuts on the bar

        public static func soundtrack(duration: Double) -> Score? {
            Score(duration: duration) {
                chordPad(.minor7(.a3), at: 0, duration: bar * 2)
                chordPad(.major7(.f3), at: bar * 2, duration: duration - bar * 2)
                thump(at: bar)                               // mark cuts with hits, never whoosh/riser
            }
        }

        @MainActor public static func body(at t: Double, duration: Double) -> some View {
            ZStack {
                Color.black
                Timeline(t) {
                    Clip(bar) { l in title("Hello", l) }.named("Title")
                    Clip(duration) { l in title("world.", l) }.transition(.fade(0.4)).named("World")
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        }

        static func title(_ s: String, _ l: Double) -> some View {
            let p = Ease.easeOut(Ease.clip(l, 0, 0.6))          // 0→1 over the clip's first 0.6 s
            return Text(s).font(.system(size: 140, weight: .bold)).foregroundStyle(.white)
                .opacity(p).scaleEffect(Ease.spring(l, from: 1.15, to: 1, response: 0.45, dampingFraction: 0.7))
        }
    }
    ```

    \(HouseRules.text)
    """

    /// What new_scene returns after the file is created.
    static func newSceneNote(name: String, kind: String) -> String {
        """
        Write it as a pure function of time:
        - `body(at t:, duration:\(kind == "audio" ? ", audio:" : ""))` returns the frame at t — no @State, Timer, Date(), \
        onAppear or withAnimation; everything moves because t moves.
        - `Ease.easeOut(Ease.clip(t, 0.2, 0.8))` is 0…1 progress inside a time window; `Ease.spring(t, from:to:response:dampingFraction:)` overshoots analytically.
        - `Timeline(t) { Clip(2) { l in … }.named("Title"); Clip(3) { l in … }.transition(.fade(0.4)) }` runs shots in local time l.
        - `soundtrack(duration:)` returns a `Score`: harmony (chordPad, arpeggio, melody) and hits on cuts (thump, rim, tick, swell) — never whoosh or riser.
        - Fill the frame: `.frame(maxWidth: .infinity, maxHeight: .infinity)` over a background color.\
        \(kind == "audio" ? "\n- `audio.band(.bass, at: t)` is 0…1 energy; render with an audio file or the scene's own score." : "")
        Next: contact_sheet {scene:"\(name)"} builds it and shows the whole film → edit (no file tools? write_scene \
        {name:"\(name)", source}) → render_frames for details → check_scene → render_video. More: docs {topic:"scenes"}, \
        {topic:"timeline"}, {topic:"sound"}.
        """
    }
}
